INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7268166, 1130141, 20056, '<td valign="top">Thanks for the comments (the real thing that matters), I feel I failed somehow because there wasn''t many comments in the picture.<br/> <br/>The dark objects are actually rocks :), beautiful rocks we found in our trips.<br/> <br/>I applied again oilpaint filter to give the melting feeling except in the red ice cube (red laser pointer light)<br/> <br/>Cheers, and I hope I get more comments this week ;)</td>', 'Thanks for the comments (the real thing that matters), I feel I failed somehow because there wasn''t many comments in the picture. The dark objects are actually rocks :), beautiful rocks we found in our trips. I applied again oilpaint filter to give the melting feeling except in the red ice cube (red laser pointer light) Cheers, and I hope I get more comments this week ;)', '2014-10-01 09:18:14.000000', NULL, 0),
(7268173, 1130136, 20056, '<td valign="top">Just my 2 cents...<br/>I think it didn''t get too much points because the sky was the main subject, maybe another angle showing more water (and still some sky) would have workked better. Even the platform could be removed for strength and simplicity.<br/>I don''t think cropping would help because people wouldn''t understand the nice lighting in the water.<br/> <br/>Cheers and thanks for your comments.</td>', 'Just my 2 cents...I think it didn''t get too much points because the sky was the main subject, maybe another angle showing more water (and still some sky) would have workked better. Even the platform could be removed for strength and simplicity.I don''t think cropping would help because people wouldn''t understand the nice lighting in the water. Cheers and thanks for your comments.', '2014-10-01 09:27:12.000000', NULL, 0),
(7268174, 1130251, 20056, '<td valign="top">A  subject so close to burning is very risky in challenges... You never know what kind of monitors people have.<br/>You got a very nice and tricky one... exposure had to be carefully measured.<br/> <br/>Cheers and thanks for your comments.</td>', 'A  subject so close to burning is very risky in challenges... You never know what kind of monitors people have.You got a very nice and tricky one... exposure had to be carefully measured. Cheers and thanks for your comments.', '2014-10-01 09:31:43.000000', NULL, 0),
(7268182, 1130474, 135744, '<td valign="top">Love it! Very nice indeed.</td>', 'Love it! Very nice indeed.', '2014-10-01 10:14:34.000000', NULL, 0),
