(7268200, 1130331, 170281, '<td valign="top">Congratulations on the ribbon!  Well deserved and worth the travels to the location for capturing this shot.</td>', 'Congratulations on the ribbon!  Well deserved and worth the travels to the location for capturing this shot.', '2014-10-01 11:12:33.000000', NULL, 0),
